pub(crate) fn start_qwen3_with_lora_control(
    model_path: &str,
    enable_cuda_graph: bool,
    device_ordinals: &[usize],
    seed: u64,
    lora_options: Qwen3LoraOptions,
    offload_options: Qwen3OffloadOptions,
    no_prefix_cache: bool,
    max_prefill_tokens: usize,
    memory_options: Qwen3MemoryOptions,
) -> Result<Engine> {
    let mut executor = Qwen3Executor::from_runtime_with_lora_options(
        model_path,
        enable_cuda_graph,
        device_ordinals,
        lora_options,
        offload_options,
        max_prefill_tokens,
        None,
        memory_options,
    )?;
    executor.set_no_prefix_cache(no_prefix_cache);
    Ok(start_with_executor(
        executor,
        seed,
        max_prefill_tokens,
        true,
    ))

    } else {
        Err("--kv-offload-host-gib must be a positive, finite number of GiB".to_owned())
    }
}

